def findNumberOfPerfectPairs(arr):
    a = sorted(abs(x) for x in arr)
    n, ans, j = len(a), 0, 0
    for i in range(n):
        j = max(j, i + 1)
        while j < n and a[j] <= 2 * a[i]:
            j += 1
        ans += j - i - 1        # a[i+1 .. j-1] 都能和 a[i] 配成完美对
    return ans
